/**
 * Chase Paymentech gateway adapter — ported from EdgePay-Gateway-Plugin/chase-paymentech.
 * GENERATED by scripts/port-gateways/generate.py — regenerate, do not hand-edit.
 * Flow: rest.
 * PORT-NOTE: sandbox "simulation" fallback (SIM_/uniqid fake success) stripped — API failure now throws.
 * PORT-NOTE: upstream refund is a simulation (no API call) — ported as refund_not_supported.
 * PORT-NOTE: upstream webhook check was a stub/presence-only — ported fail-closed.
 */

import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type RefundResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';

const SLUG = "chase-paymentech";

export class ChasePaymentechGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "Chase Paymentech",
      slug: "chase-paymentech",
      version: '1.0.0',
      description: "Chase Paymentech payment gateway integration for EdgePay",
      author: 'EdgePay Gateway Plugin Suite (AGPLv3) — EdgePay port',
      type: 'gateway',
      supported_currencies: [],
      capabilities: ["verification"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "merchant_id", label: "Merchant ID", type: "text" as const, required: true },
      { name: "terminal_id", label: "Terminal ID", type: "text" as const, required: true },
      { name: "bin", label: "BIN (e.g. 000001)", type: "text" as const, required: true },
    ];
  }

  async initiate(params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const mode = String(credentials.mode ?? 'sandbox');
    const endpoint = (String(mode) === String("live")) ? ("https://ws.paymentech.net/PaymentechGateway/process") : ("https://wsvar.paymentech.net/PaymentechGateway/process");
    const payload = { ["reference"]: (params.trx_id ?? ''), ["amount"]: (params.amount ?? ''), ["currency"]: (params.currency ?? ''), ["redirect_url"]: (params.redirect_url ?? ''), ["cancel_url"]: (params.cancel_url ?? '') };
    const res = await gwJson({
      url: endpoint,
      method: 'POST',
      headers: { ["Content-Type"]: "application/json", ["User-Agent"]: "EdgePay Gateway Client/1.0.0" },
      body: JSON.stringify(payload),
      timeoutMs: 15000,
    });
    if (res.status !== 200) throw new Error(`${SLUG}: HTTP ${res.status} ${res.text}`);
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    return {
          redirect_url: (String(((d) as Record<string, unknown>)["payment_url"] ?? '') || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["reference"] ?? '') === '') {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const mode = String(credentials.mode ?? 'sandbox');
    const endpoint = (String(mode) === String("live")) ? (`https://ws.paymentech.net/PaymentechGateway/verify${String(cb["reference"])}`) : (`https://wsvar.paymentech.net/PaymentechGateway/verify${String(cb["reference"])}`);
    const res = await gwJson({
      url: endpoint,
      method: 'GET',
      headers: { ["User-Agent"]: "EdgePay Gateway Client/1.0.0" },
      timeoutMs: 10000,
    });
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const d = res.data as Record<string, unknown>;
    const ok = (res.data !== null) && (String((((d) as Record<string, unknown>)["status"] ?? "")) === String("PAID"));
    return {
          success: ok,
          gateway_trx_id: String(String(((d) as Record<string, unknown>)["gateway_trx_id"] ?? '') ?? ''),
          amount: (String(String(((d) as Record<string, unknown>)["amount"] ?? '') ?? '') || null) as string | null,
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
        };
  }

  async verifyWebhook(_input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    // PORT-SECURITY: upstream accepted these webhooks without a signature
    // check (stub / header-presence only). Ported FAIL-CLOSED: unsigned
    // events are rejected. Payments complete via the signed checkout
    // callback + server-side verify() instead.
    return false;
  }

  // PORT-SECURITY: upstream PHP faked refund success without any
  // provider API call. A fake refund ID would post ledger entries for
  // money that never moved — this port reports refund_not_supported.
  async refund(_gatewayTrxId: string, _amount: string, _credentials: Credentials): Promise<RefundResult> {
    return { success: false, error: 'refund_not_supported' };
  }
}
